select a.*
from COLLECT_DS a
where COLLECT_CODE = (
    select MAX(to_number(COLLECT_CODE)) AS code
    from COLLECT_DS
    where ASSET_ID = #{assetId}
      and TYPE = #{type}
)
  and ASSET_ID = #{assetId}
  and TYPE = #{type}

SELECT MAX(COLLECT_TIME) AS code
from COLLECT_DS
where ASSET_ID = #{assetId}

select a.*
from COLLECT_DS a
where COLLECT_CODE = (
    select MAX(to_number(COLLECT_CODE)) AS code
    from COLLECT_DS
    where ASSET_ID = #{assetId}
      and TYPE = #{type}
)
  and ASSET_ID = #{assetId}
  and TYPE = #{type}
  and Y_INDEX = #{index}
